PAGE = """
<!DOCTYPE html>
<html lang="{{ t.lang_code }}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{{ t.brand }} | {{ t.brand_alt }}</title>
<meta name="description" content="{{ t.hero_text }}">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600&family=Source+Sans+3:wght@400;500;600&family=Noto+Serif+SC:wght@500;700&display=swap" rel="stylesheet">
<style>
  /* ------------------------------------------------------------------
     COLOURS  (from the shop signboard: purple board, brown lettering)
     ------------------------------------------------------------------ */
  :root{
    --purple:#3E1854;     /* main purple: hero, buttons */
    --purple-soft:#F4EFF7;/* very light purple for small areas */
    --brown:#A87B45;      /* signboard brown: accents only */
    --brown-dark:#2B1B12; /* headings and footer */
    --text:#554238;       /* body text */
    --muted:#8A7A70;      /* captions */
    --line:#E8E1EA;       /* thin dividers */
    --white:#FFFFFF;

    --serif:"Cormorant Garamond", "Noto Serif SC", Georgia, serif;
    --sans:"Source Sans 3", "Noto Serif SC", system-ui, -apple-system, "Segoe UI", sans-serif;
    --cn:"Noto Serif SC", "Songti SC", "SimSun", serif;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html{scroll-behavior:smooth;scroll-padding-top:72px}
  body{font-family:var(--sans);font-size:17px;line-height:1.7;color:var(--text);background:var(--white)}
  img{max-width:100%;display:block}
  a{color:inherit}
  :focus-visible{outline:2px solid var(--brown);outline-offset:3px}
  .wrap{max-width:1120px;margin:0 auto;padding-left:32px;padding-right:32px}
  h1,h2,h3{font-family:var(--serif);color:var(--brown-dark);font-weight:600;line-height:1.15}
  html[lang="zh"] h1, html[lang="zh"] h2, html[lang="zh"] h3{font-family:var(--cn);font-weight:700}

  /* ---------------- HEADER ---------------- */
  header{position:sticky;top:0;z-index:50;background:var(--white);border-bottom:1px solid var(--line)}
  nav{display:flex;align-items:center;justify-content:space-between;height:68px;gap:24px}
  .brand{text-decoration:none;font-family:var(--serif);font-weight:600;font-size:22px;color:var(--purple)}
  html[lang="zh"] .brand{font-family:var(--cn);font-size:19px}
  .links{display:flex;align-items:center;gap:36px}
  .links a{text-decoration:none;font-size:15px;color:var(--text)}
  .links a:hover{color:var(--purple)}
  .links .lang{color:var(--brown);font-weight:600}
  .menu-btn{display:none;background:none;border:0;width:40px;height:40px;cursor:pointer;position:relative}
  .menu-btn span,.menu-btn span::before,.menu-btn span::after{position:absolute;left:9px;width:22px;height:1.5px;background:var(--brown-dark);content:""}
  .menu-btn span{top:19px}
  .menu-btn span::before{top:-7px;left:0}
  .menu-btn span::after{top:7px;left:0}

  /* ---------------- HERO ---------------- */
  .hero{background:var(--purple);color:#E6DAEE}
  .hero .wrap{padding-top:96px;padding-bottom:72px}
  .hero-tag{font-size:15px;color:var(--brown);margin-bottom:28px}
  .hero-mark{font-family:var(--cn);font-weight:700;color:var(--brown);font-size:clamp(44px,7vw,80px);line-height:1;letter-spacing:.08em;margin-bottom:16px}
  html[lang="zh"] .hero-mark{font-family:var(--serif);font-weight:600;letter-spacing:0;font-size:clamp(34px,5vw,56px)}
  .hero h1{color:var(--white);font-size:clamp(36px,4.5vw,56px);font-weight:500;margin-bottom:24px}
  html[lang="zh"] .hero h1{letter-spacing:.08em}
  .hero-text{font-size:19px;max-width:32em;margin-bottom:40px}
  .btns{display:flex;flex-wrap:wrap;gap:12px}
  .btn{display:inline-block;text-decoration:none;font-weight:600;font-size:15px;padding:13px 26px;border:1px solid transparent;transition:background .2s,color .2s,border-color .2s}
  .btn-solid{background:var(--brown);color:var(--white)}
  .btn-solid:hover{background:#8F6636}
  .btn-line{border-color:rgba(255,255,255,.4);color:var(--white)}
  .btn-line:hover{border-color:var(--white)}
  .hero-grid{display:grid;grid-template-columns:1fr 460px;gap:64px;align-items:center}
  .facts{display:flex;flex-wrap:wrap;gap:0;margin-top:72px;border-top:1px solid rgba(255,255,255,.15)}

  /* hero photos */
  .mosaic{display:grid;grid-template-columns:1.25fr 1fr;grid-template-rows:210px 210px;gap:10px}
  .mosaic img{width:100%;height:100%;object-fit:cover}
  .mosaic .m-tall{grid-row:1 / span 2}
  .mosaic figcaption{grid-column:1 / -1;font-size:13px;color:#BFAECB;padding-top:6px}
  .fact{padding:24px 0 0 0;margin-right:44px}
  .fact b{display:block;font-family:var(--serif);font-weight:600;font-size:28px;color:var(--white);line-height:1.2}
  .fact span{font-size:14px;color:#BFAECB}

  /* ---------------- SECTIONS ---------------- */
  section{padding:112px 0}
  .head{max-width:600px;margin-bottom:48px}
  .head h2{font-size:clamp(32px,3.6vw,44px);margin-bottom:10px}
  .head p{color:var(--muted)}

  /* gallery: big photo left, two smaller on the right */
  .gallery{display:grid;grid-template-columns:1.5fr 1fr;grid-template-rows:250px 250px;gap:16px}
  .gallery figure{position:relative;overflow:hidden;min-height:0}
  .gallery figure:first-child{grid-row:1 / span 2}
  .gallery img{width:100%;height:100%;object-fit:cover}
  .gallery figcaption{position:absolute;left:0;right:0;bottom:0;padding:32px 18px 14px;font-size:14px;color:#fff;background:linear-gradient(transparent,rgba(20,10,25,.7))}
  .credit{margin-top:18px;font-size:14px;color:var(--muted)}

  /* story */
  .story{border-top:1px solid var(--line)}
  .story-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px}
  .story p{margin-bottom:18px;max-width:34em}
  .quote{border-left:2px solid var(--brown);padding-left:28px;align-self:start;margin-top:8px}
  .quote p{font-family:var(--serif);font-size:30px;line-height:1.35;color:var(--purple);margin-bottom:14px}
  html[lang="zh"] .quote p{font-family:var(--cn);font-size:22px;line-height:1.7}
  .quote cite{font-style:normal;font-size:14px;color:var(--muted)}
  .values{display:grid;grid-template-columns:repeat(3,1fr);gap:48px;margin-top:80px;padding-top:40px;border-top:1px solid var(--line)}
  .value h3{font-size:24px;margin-bottom:8px}
  html[lang="zh"] .value h3{font-size:19px}
  .value p{font-size:16px;margin:0}

  /* visit */
  .visit{background:var(--purple-soft)}
  .visit-grid{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:48px;align-items:start}
  .info h3{font-family:var(--sans);font-size:14px;font-weight:600;color:var(--brown);margin-bottom:8px}
  .info p{white-space:pre-line}
  .phone{font-family:var(--serif);font-size:30px;font-weight:600;color:var(--purple);text-decoration:none;line-height:1.2}
  .phone:hover{color:var(--brown)}
  .map{text-align:center;width:220px}
  .qr{width:150px;margin:0 auto 14px;border:1px solid var(--line);background:#fff;padding:8px}
  .map p{font-size:13px;color:var(--muted);margin-bottom:14px}
  .btn-purple{background:var(--purple);color:#fff;width:100%;padding:13px 16px;white-space:nowrap}
  .btn-purple:hover{background:#2C1040}

  /* footer */
  footer{background:var(--brown-dark);color:#B3A397;padding:32px 0;font-size:13.5px}
  footer .wrap{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}

  /* ---------------- RESPONSIVE ---------------- */
  @media (max-width:960px){
    .hero-grid{grid-template-columns:1fr;gap:56px}
    .mosaic{grid-template-rows:170px 170px}
    .story-grid{grid-template-columns:1fr;gap:48px}
    .visit-grid{grid-template-columns:1fr 1fr}
    .map{width:auto;text-align:left}
    .qr{margin:0 0 14px}
    .btn-purple{width:auto}
  }
  @media (max-width:760px){
    .wrap{padding-left:22px;padding-right:22px}
    .menu-btn{display:block}
    .links{display:none;position:absolute;top:68px;left:0;right:0;background:var(--white);flex-direction:column;align-items:flex-start;gap:14px;padding:20px 22px 24px;border-bottom:1px solid var(--line)}
    .links.open{display:flex}
    .hero .wrap{padding-top:72px;padding-bottom:48px}
    .facts{margin-top:64px}
    .fact{padding-right:0;margin-right:32px}
    .fact b{font-size:22px}
    section{padding:80px 0}
    .gallery{grid-template-columns:1fr;grid-template-rows:auto}
    .gallery figure:first-child{grid-row:auto}
    .gallery img{height:auto;aspect-ratio:4/3}
    .values{grid-template-columns:1fr;gap:28px;margin-top:56px}
    .visit-grid{grid-template-columns:1fr;gap:32px}
  }
</style>
</head>
<body>

<header>
  <nav class="wrap" aria-label="Main">
    <a class="brand" href="{{ url_for('home', lang=t.lang_code) }}">{{ t.brand }}</a>
    <button class="menu-btn" id="menuBtn" aria-label="{{ t.nav_toggle }}" aria-expanded="false" aria-controls="navLinks"><span></span></button>
    <div class="links" id="navLinks">
      <a href="#home">{{ t.nav.home }}</a>
      <a href="#gallery">{{ t.nav.menu }}</a>
      <a href="#about">{{ t.nav.about }}</a>
      <a href="#visit">{{ t.nav.visit }}</a>
      <a class="lang" href="{{ url_for('home', lang=t.other_lang) }}" lang="{{ t.other_lang }}">{{ t.other_lang_label }}</a>
    </div>
  </nav>
</header>

<div class="hero" id="home">
  <div class="wrap hero-grid">
   <div class="hero-copy">
    <p class="hero-tag">{{ t.hero_tag }}</p>
    <p class="hero-mark" aria-hidden="true">{{ t.hero_mark }}</p>
    <h1>{{ t.hero_title }}</h1>
    <p class="hero-text">{{ t.hero_text }}</p>
    <div class="btns">
      <a class="btn btn-solid" href="#visit">{{ t.hero_btn2 }}</a>
      <a class="btn btn-line" href="#gallery">{{ t.hero_btn1 }}</a>
    </div>
    <div class="facts">
      {% for n, l in t.stats %}
      <div class="fact"><b>{{ n }}</b><span>{{ l }}</span></div>
      {% endfor %}
    </div>
   </div>

   <!-- HERO PHOTOS: one tall + two stacked -->
   <figure class="mosaic">
    <img class="m-tall" src="{{ url_for('photo', key='hero_hokkien') }}" alt="{{ t.hero_title }}">
    <img src="{{ url_for('photo', key='hero_douqian') }}" alt="">
    <img src="{{ url_for('photo', key='hero_fishcake') }}" alt="">
    <figcaption>{{ t.hero_photos_note }}</figcaption>
   </figure>
  </div>
</div>

<section id="gallery">
  <div class="wrap">
    <div class="head">
      <h2>{{ t.gallery_title }}</h2>
      <p>{{ t.gallery_sub }}</p>
    </div>
    <div class="gallery">
      {% for key, caption in t.gallery %}
      <figure>
        <img src="{{ url_for('photo', key=key) }}" alt="{{ caption }}" loading="lazy">
        <figcaption>{{ caption }}</figcaption>
      </figure>
      {% endfor %}
    </div>
    <p class="credit">{{ t.gallery_credit }}</p>
  </div>
</section>

<section class="story" id="about">
  <div class="wrap">
    <div class="story-grid">
      <div>
        <div class="head" style="margin-bottom:28px"><h2>{{ t.about_title }}</h2></div>
        <p>{{ t.about_p1 }}</p>
        <p>{{ t.about_p2 }}</p>
      </div>
      <blockquote class="quote">
        <p>&ldquo;{{ t.quote }}&rdquo;</p>
        <cite>{{ t.quote_by }}</cite>
      </blockquote>
    </div>
    <div class="values">
      {% for title, text in t.features %}
      <div class="value"><h3>{{ title }}</h3><p>{{ text }}</p></div>
      {% endfor %}
    </div>
  </div>
</section>

<section class="visit" id="visit">
  <div class="wrap">
    <div class="head">
      <h2>{{ t.visit_title }}</h2>
      <p>{{ t.visit_sub }}</p>
    </div>
    <div class="visit-grid">
      <div class="info"><h3>{{ t.addr_label }}</h3><p>{{ t.addr }}</p></div>
      <div class="info"><h3>{{ t.hours_label }}</h3><p>{{ t.hours }}</p></div>
      <div class="info"><h3>{{ t.phone_label }}</h3><a class="phone" href="tel:+60166778883">{{ t.phone }}</a></div>
      <div class="map">
        <img class="qr" src="{{ url_for('photo', key='qr') }}" alt="{{ t.qr_alt }}">
        <p>{{ t.map_sub }}</p>
        <a class="btn btn-purple" href="{{ maps_url }}" target="_blank" rel="noopener">{{ t.map_btn }}</a>
      </div>
    </div>
  </div>
</section>

<footer>
  <div class="wrap">
    <div>&copy; {{ year }} {{ t.brand }}. {{ t.footer }}</div>
    <div>{{ t.footer_reg }}</div>
  </div>
</footer>

<script>
  // Mobile navigation toggle
  (function(){
    var btn = document.getElementById('menuBtn');
    var links = document.getElementById('navLinks');
    btn.addEventListener('click', function(){
      var open = links.classList.toggle('open');
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
    links.querySelectorAll('a').forEach(function(a){
      a.addEventListener('click', function(){
        links.classList.remove('open');
        btn.setAttribute('aria-expanded', 'false');
      });
    });
  })();
</script>
</body>
</html>
"""


# ---------------------------------------------------------------------------
# HELPERS
# ---------------------------------------------------------------------------
def pick_lang():
    """Query string wins, then cookie, then English."""
    lang = request.args.get("lang") or request.cookies.get("lang") or "en"
    return lang if lang in T else "en"


# Matches every emoji (and emoji written as HTML codes like &#127760;)
EMOJI = re.compile(
    "[\U0001F000-\U0001FAFF\u2600-\u27BF\u2B00-\u2BFF\uFE0F\u200D]+"
    "|&#(?:1[2-3][0-9]{4}|x1F[0-9A-Fa-f]{3});"
)


def remove_emoji(text):
    return EMOJI.sub("", text)


def render():
    lang = pick_lang()
    html = render_template_string(
        PAGE, t=T[lang], year=2026, images=IMAGES, maps_url=MAPS_URL
    )
    html = remove_emoji(html)  # safety net: no emoji can reach the page
    resp = make_response(html)
    resp.headers["Cache-Control"] = "no-store"  # browser always loads the newest version
    resp.set_cookie("lang", lang, max_age=60 * 60 * 24 * 365)
    return resp


# ---------------------------------------------------------------------------
# ROUTES
# ---------------------------------------------------------------------------
@app.route("/")
def home():
    return render()


@app.route("/photo/<key>")
def photo(key):
    """Serves one embedded photo, so the page itself stays light and fast."""
    if key not in IMAGES:
        return "Photo not found", 404
    data = base64.b64decode(IMAGES[key])
    resp = make_response(data)
    resp.headers["Content-Type"] = "image/png" if key == "qr" else "image/jpeg"
    resp.headers["Cache-Control"] = "public, max-age=86400"
    return resp


if __name__ == "__main__":
    print("One Kee website (new design, no emoji) running at http://127.0.0.1:5000")
    app.run(debug=True, use_reloader=False)